class Solution {
    public String findLatestTime(String s) {
        char[] chars = s.toCharArray();
        if (chars[0] == '?') {
            chars[0] = (chars[1] == '0' || chars[1] == '1' || chars[1] == '?') ? '1' : '0';
        }
        if (chars[1] == '?') {
            chars[1] = (chars[0] == '1') ? '1' : '9';
        }
        if (chars[3] == '?') {
            chars[3] = '5';
        }
        if (chars[4] == '?') {
            chars[4] = '9';
        }
        return new String(chars);
    }
}

var findLatestTime = function(s) {
    const chars = s.split('');
    if (chars[0] === '?') {
        chars[0] = (chars[1] === '0' || chars[1] === '1' || chars[1] === '?') ? '1' : '0';
    }
    if (chars[1] === '?') {
        chars[1] = (chars[0] === '1') ? '1' : '9';
    }
    if (chars[3] === '?') {
        chars[3] = '5';
    }
    if (chars[4] === '?') {
        chars[4] = '9';
    }
    return chars.join('');
};
